//! The About window: the app's name, version and maker, its own license, and
//! the licenses of everything it includes. The texts are compiled in, so
//! every build carries the notices its licenses require.

use serde::Serialize;
use tauri::{AppHandle, Manager, WebviewUrl, WebviewWindow, WebviewWindowBuilder};

/// The one About window; capabilities grant it by this label.
pub const LABEL: &str = "about";

const LICENSE: &str = include_str!("../../LICENSE");
/// Regenerated by `tools/third-party-notices.sh`.
const NOTICES: &str = include_str!("../../THIRD-PARTY-NOTICES.txt");

/// Opens the About window, or brings it to the front.
pub fn open(app: &AppHandle) -> tauri::Result<()> {
    if let Some(window) = app.get_webview_window(LABEL) {
        let _ = window.unminimize();
        let _ = window.show();
        return window.set_focus();
    }
    WebviewWindowBuilder::new(app, LABEL, WebviewUrl::App("about.html".into()))
        .title(format!("About {}", app.package_info().name))
        .inner_size(760.0, 720.0)
        .min_inner_size(480.0, 360.0)
        .disable_drag_drop_handler()
        .build()?;
    crate::menu::update_dock(app, None);
    Ok(())
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AboutInfo {
    name: String,
    version: String,
    description: String,
    repository: String,
    maker: String,
    copyright: String,
    license: String,
    notices: String,
}

#[tauri::command]
pub fn about_info(app: AppHandle) -> AboutInfo {
    let info = app.package_info();
    AboutInfo {
        name: info.name.clone(),
        version: info.version.to_string(),
        description: env!("CARGO_PKG_DESCRIPTION").to_owned(),
        repository: env!("CARGO_PKG_REPOSITORY").to_owned(),
        maker: crate::menu::MAKER.to_owned(),
        copyright: app.config().bundle.copyright.clone().unwrap_or_default(),
        license: LICENSE.to_owned(),
        notices: NOTICES.to_owned(),
    }
}

/// Closes the About window (Esc). Other windows can't be closed this way.
#[tauri::command]
pub fn close_about(window: WebviewWindow) -> Result<(), String> {
    if window.label() != LABEL {
        return Err(format!("not the About window: {}", window.label()));
    }
    let _ = window.close();
    Ok(())
}
